// Dados simulados de Stories
const storiesData = [
  { username: "seu_story", avatar: "https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=150&q=80" },
    { username: "ana.travels", avatar: "https://images.unsplash.com/photo-1494790108377-be9c29b29330?w=150&q=80" },
      { username: "carlos_dev", avatar: "https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=150&q=80" },
        { username: "julia.arte", avatar: "https://images.unsplash.com/photo-1438761681033-6461ffad8d80?w=150&q=80" },
          { username: "marcos_fit", avatar: "https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=150&q=80" }
          ];

          // Dados simulados de Posts
          let postsData = [
            {
                id: 1,
                    username: "ana.travels",
                        avatar: "https://images.unsplash.com/photo-1494790108377-be9c29b29330?w=150&q=80",
                            image: "https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800&q=80",
                                likes: 148,
                                    liked: false,
                                        caption: "Fim de tarde incrível nas montanhas! 🌄✨",
                                            time: "HÁ 2 HORAS",
                                                comments: [
                                                      { user: "carlos_dev", text: "Que foto espetacular!" }
                                                          ]
                                                            },
                                                              {
                                                                  id: 2,
                                                                      username: "carlos_dev",
                                                                          avatar: "https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=150&q=80",
                                                                              image: "https://images.unsplash.com/photo-1498050108023-c5249f4df085?w=800&q=80",
                                                                                  likes: 92,
                                                                                      liked: true,
                                                                                          caption: "Setup pronto para mais um projeto em JavaScript 💻☕",
                                                                                              time: "HÁ 5 HORAS",
                                                                                                  comments: []
                                                                                                    }
                                                                                                    ];

                                                                                                    const storiesBar = document.getElementById("storiesBar");
                                                                                                    const feed = document.getElementById("feed");
                                                                                                    const postModal = document.getElementById("postModal");
                                                                                                    const openModalBtn = document.getElementById("openModalBtn");
                                                                                                    const closeModalBtn = document.getElementById("closeModalBtn");
                                                                                                    const newPostForm = document.getElementById("newPostForm");

                                                                                                    // Renderiza os Stories
                                                                                                    function renderStories() {
                                                                                                      storiesBar.innerHTML = storiesData.map(story => `
                                                                                                          <div class="story-item">
                                                                                                                <div class="story-ring">
                                                                                                                        <img src="${story.avatar}" alt="${story.username}">
                                                                                                                              </div>
                                                                                                                                    <span class="story-user">${story.username}</span>
                                                                                                                                        </div>
                                                                                                                                          `).join("");
                                                                                                                                          }

                                                                                                                                          // Escapa caracteres HTML por segurança
                                                                                                                                          function escapeHTML(str) {
                                                                                                                                            const div = document.createElement("div");
                                                                                                                                              div.textContent = str;
                                                                                                                                                return div.innerHTML;
                                                                                                                                                }

                                                                                                                                                // Renderiza o Feed
                                                                                                                                                function renderFeed() {
                                                                                                                                                  feed.innerHTML = "";

                                                                                                                                                    postsData.forEach(post => {
                                                                                                                                                        const commentsHTML = post.comments.map(c => `
                                                                                                                                                              <div class="comment-item">
                                                                                                                                                                      <strong>${escapeHTML(c.user)}</strong> ${escapeHTML(c.text)}
                                                                                                                                                                            </div>
                                                                                                                                                                                `).join("");

                                                                                                                                                                                    const article = document.createElement("article");
                                                                                                                                                                                        article.className = "post-card";
                                                                                                                                                                                            article.innerHTML = `
                                                                                                                                                                                                  <div class="post-header">
                                                                                                                                                                                                          <img src="${post.avatar}" alt="${post.username}" class="avatar">
                                                                                                                                                                                                                  <span class="username">${escapeHTML(post.username)}</span>
                                                                                                                                                                                                                        </div>

                                                                                                                                                                                                                              <div class="post-image-container" ondblclick="doubleClickLike(${post.id}, this)">
                                                                                                                                                                                                                                      <img src="${post.image}" alt="Publicação" class="post-image">
                                                                                                                                                                                                                                              <span class="heart-overlay">♥</span>
                                                                                                                                                                                                                                                    </div>

                                                                                                                                                                                                                                                          <div class="post-actions">
                                                                                                                                                                                                                                                                  <button class="icon-btn ${post.liked ? "liked" : ""}" onclick="toggleLike(${post.id})">
                                                                                                                                                                                                                                                                            ${post.liked ? "♥" : "♡"}
                                                                                                                                                                                                                                                                                    </button>
                                                                                                                                                                                                                                                                                            <button class="icon-btn" onclick="focusComment(${post.id})">💬</button>
                                                                                                                                                                                                                                                                                                  </div>

                                                                                                                                                                                                                                                                                                        <div class="post-likes">${post.likes} curtidas</div>

                                                                                                                                                                                                                                                                                                              <div class="post-caption">
                                                                                                                                                                                                                                                                                                                      <strong>${escapeHTML(post.username)}</strong> ${escapeHTML(post.caption)}
                                                                                                                                                                                                                                                                                                                            </div>

                                                                                                                                                                                                                                                                                                                                  <div class="post-comments">${commentsHTML}</div>
                                                                                                                                                                                                                                                                                                                                        <div class="post-time">${post.time}</div>

                                                                                                                                                                                                                                                                                                                                              <form class="comment-form" onsubmit="addComment(event, ${post.id})">
                                                                                                                                                                                                                                                                                                                                                      <input type="text" id="comment-input-${post.id}" placeholder="Adicione um comentário..." required>
                                                                                                                                                                                                                                                                                                                                                              <button type="submit">Publicar</button>
                                                                                                                                                                                                                                                                                                                                                                    </form>
                                                                                                                                                                                                                                                                                                                                                                        `;
                                                                                                                                                                                                                                                                                                                                                                            feed.appendChild(article);
                                                                                                                                                                                                                                                                                                                                                                              });
                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                              // Curtir / Descurtir pelo botão
                                                                                                                                                                                                                                                                                                                                                                              function toggleLike(id) {
                                                                                                                                                                                                                                                                                                                                                                                const post = postsData.find(p => p.id === id);
                                                                                                                                                                                                                                                                                                                                                                                  if (!post) return;

                                                                                                                                                                                                                                                                                                                                                                                    post.liked = !post.liked;
                                                                                                                                                                                                                                                                                                                                                                                      post.likes += post.liked ? 1 : -1;
                                                                                                                                                                                                                                                                                                                                                                                        renderFeed();
                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                        // Curtir com duplo clique na imagem
                                                                                                                                                                                                                                                                                                                                                                                        function doubleClickLike(id, container) {
                                                                                                                                                                                                                                                                                                                                                                                          const post = postsData.find(p => p.id === id);
                                                                                                                                                                                                                                                                                                                                                                                            if (!post) return;

                                                                                                                                                                                                                                                                                                                                                                                              const heart = container.querySelector(".heart-overlay");
                                                                                                                                                                                                                                                                                                                                                                                                heart.classList.add("show");

                                                                                                                                                                                                                                                                                                                                                                                                  setTimeout(() => {
                                                                                                                                                                                                                                                                                                                                                                                                      heart.classList.remove("show");
                                                                                                                                                                                                                                                                                                                                                                                                          if (!post.liked) {
                                                                                                                                                                                                                                                                                                                                                                                                                post.liked = true;
                                                                                                                                                                                                                                                                                                                                                                                                                      post.likes += 1;
                                                                                                                                                                                                                                                                                                                                                                                                                            renderFeed();
                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                  }, 600);
                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                  // Foca no campo de comentário ao clicar no balão
                                                                                                                                                                                                                                                                                                                                                                                                                                  function focusComment(id) {
                                                                                                                                                                                                                                                                                                                                                                                                                                    const input = document.getElementById(`comment-input-${id}`);
                                                                                                                                                                                                                                                                                                                                                                                                                                      if (input) input.focus();
                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                      // Adiciona comentário
                                                                                                                                                                                                                                                                                                                                                                                                                                      function addComment(event, id) {
                                                                                                                                                                                                                                                                                                                                                                                                                                        event.preventDefault();
                                                                                                                                                                                                                                                                                                                                                                                                                                          const input = document.getElementById(`comment-input-${id}`);
                                                                                                                                                                                                                                                                                                                                                                                                                                            const text = input.value.trim();
                                                                                                                                                                                                                                                                                                                                                                                                                                              if (!text) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                const post = postsData.find(p => p.id === id);
                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (post) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                      post.comments.push({ user: "voce", text });
                                                                                                                                                                                                                                                                                                                                                                                                                                                          renderFeed();
                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                            // Controle do Modal de nova foto
                                                                                                                                                                                                                                                                                                                                                                                                                                                            openModalBtn.addEventListener("click", () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                              postModal.style.display = "flex";
                                                                                                                                                                                                                                                                                                                                                                                                                                                              });

                                                                                                                                                                                                                                                                                                                                                                                                                                                              closeModalBtn.addEventListener("click", () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                postModal.style.display = "none";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                window.addEventListener("click", (e) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (e.target === postModal) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      postModal.style.display = "none";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // Cria novo post
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        newPostForm.addEventListener("submit", (e) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          e.preventDefault();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const imageUrl = document.getElementById("imageUrl").value.trim();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const caption = document.getElementById("captionInput").value.trim();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (!imageUrl || !caption) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const newPost = {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      id: Date.now(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          username: "voce",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              avatar: "https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=150&q=80",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  image: imageUrl,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      likes: 0,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          liked: false,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              caption: caption,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  time: "AGORA MESMO",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      comments: []
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          postsData.unshift(newPost);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            newPostForm.reset();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              postModal.style.display = "none";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                renderFeed();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Inicializa a interface
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                renderStories();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                renderFeed();